// Renders the declared capability table (platform.ts) as Markdown: docs/gizeverse/capability-matrix.md
// is generated by scripts/capability-matrix.mjs and a unit test fails when it is stale (ADR 0004 §2.3).
import { CAPABILITY_IDS, CAPABILITY_LABELS, CAPABILITY_MATRIX, PLATFORM_IDS, PLATFORM_LABELS, VERIFICATION_STATUSES, type VerificationStatus } from './platform';

const SHORT: Readonly<Record<VerificationStatus, string>> = {
  IMPLEMENTED_AND_LOCALLY_VERIFIED: 'VERIFIED',
  IMPLEMENTED_BUT_NOT_PLATFORM_VERIFIED: 'IMPL, UNVERIFIED',
  ARCHITECTURALLY_VALIDATED: 'ARCH',
  SIMULATED_OR_MOCK_TESTED: 'SIMULATED',
  BLOCKED_BY_PLATFORM_OR_PERMISSION: 'BLOCKED',
  NOT_IMPLEMENTED: 'NOT IMPL',
};

const MEANING: Readonly<Record<VerificationStatus, string>> = {
  IMPLEMENTED_AND_LOCALLY_VERIFIED: 'Code exists and ran on that platform here, with the result recorded in a report',
  IMPLEMENTED_BUT_NOT_PLATFORM_VERIFIED: 'Code exists behind platform checks; never executed on that platform',
  ARCHITECTURALLY_VALIDATED: 'The design is shown to fit (code reading, bundling); not implemented as a feature',
  SIMULATED_OR_MOCK_TESTED: 'Ran only against fakes or in a virtual environment (container, Xvfb, device emulation)',
  BLOCKED_BY_PLATFORM_OR_PERMISSION: 'The platform or a permission prevents it, or it is disabled because it could break an invariant',
  NOT_IMPLEMENTED: 'Nothing exists',
};

const esc = (s: string): string => s.replace(/\|/g, '\\|');

export function renderCapabilityMatrix(): string {
  const out: string[] = [];
  out.push('# GizeVerse capability matrix');
  out.push('');
  out.push('<!-- Generated from src/shared/platform.ts by `node scripts/capability-matrix.mjs`. Do not edit by hand: a unit test fails when this file is stale. -->');
  out.push('');
  out.push('What GizeCat claims about each capability on each platform. A status is a claim about **evidence**, not a promise; see ADR 0004 §2 and CONTRIBUTING.md. No platform other than Windows is supported until the app has run on it and the result is recorded.');
  out.push('');
  out.push('## Statuses');
  out.push('');
  out.push('| Short | Status | Meaning |');
  out.push('|---|---|---|');
  for (const s of VERIFICATION_STATUSES) out.push(`| ${SHORT[s]} | ${s} | ${MEANING[s]} |`);
  out.push('');
  out.push('## Overview');
  out.push('');
  out.push(`| Capability | ${PLATFORM_IDS.map((p) => PLATFORM_LABELS[p]).join(' | ')} |`);
  out.push(`|---|${PLATFORM_IDS.map(() => '---').join('|')}|`);
  for (const c of CAPABILITY_IDS) out.push(`| ${esc(CAPABILITY_LABELS[c])} | ${PLATFORM_IDS.map((p) => SHORT[CAPABILITY_MATRIX[p][c].status]).join(' | ')} |`);
  for (const p of PLATFORM_IDS) {
    out.push('');
    out.push(`## ${PLATFORM_LABELS[p]} (\`${p}\`)`);
    out.push('');
    out.push('| Capability | Status | Note | Evidence |');
    out.push('|---|---|---|---|');
    for (const c of CAPABILITY_IDS) {
      const claim = CAPABILITY_MATRIX[p][c];
      out.push(`| ${esc(CAPABILITY_LABELS[c])} | ${claim.status} | ${esc(claim.note)} | ${claim.evidence ? `[report](../../${claim.evidence})` : '—'} |`);
    }
  }
  out.push('');
  return out.join('\n');
}
